using ComboBox=System.Windows.Controls.ComboBox;
namespace VisionEditor;
public sealed class GroupComplexEditor:Window{
 readonly NodeDocument node;readonly ModuleDescriptor descriptor;readonly ParameterDescriptor parameter;readonly Action<IReadOnlyDictionary<string,JsonElement>,IReadOnlyList<RoiDocument>?> save;readonly Dictionary<string,TextBox> fields=new();readonly TextBlock error=new(){Foreground=System.Windows.Media.Brushes.DarkRed};readonly List<RoiRow> rois;readonly DataGrid? roiGrid;readonly ComboBox? choices;
 public GroupComplexEditor(NodeDocument node,ModuleDescriptor descriptor,ParameterDescriptor parameter,Action<IReadOnlyDictionary<string,JsonElement>,IReadOnlyList<RoiDocument>?> save){this.node=node;this.descriptor=descriptor;this.parameter=parameter;this.save=save;rois=(node.Rois??[]).Select(r=>new RoiRow(r)).ToList();var editor=parameter.Editor??throw new InvalidOperationException("Missing editor metadata.");Title=node.Name+" · "+parameter.Name;Width=740;Height=480;WindowStartupLocation=WindowStartupLocation.CenterOwner;ShowInTaskbar=false;FontFamily=new System.Windows.Media.FontFamily("Microsoft YaHei");FontSize=14;var panel=new DockPanel{Margin=new Thickness(14)};var bottom=new StackPanel{Orientation=System.Windows.Controls.Orientation.Horizontal,HorizontalAlignment=System.Windows.HorizontalAlignment.Right};var confirm=new Button{Content="确定",Tag="GroupComplexConfirm",MinWidth=70};confirm.Click+=(_,_)=>Confirm();var cancel=new Button{Content="取消",MinWidth=70};cancel.Click+=(_,_)=>Close();bottom.Children.Add(error);bottom.Children.Add(confirm);bottom.Children.Add(cancel);DockPanel.SetDock(bottom,Dock.Bottom);panel.Children.Add(bottom);
  if(editor.Kind==ParameterEditorKind.Roi){var tools=new StackPanel{Orientation=System.Windows.Controls.Orientation.Horizontal};var kinds=new ComboBox{ItemsSource=new[]{RoiKind.Rectangle,RoiKind.Circle,RoiKind.Annulus},SelectedIndex=0,Tag="GroupRoiKind",Width=110};var add=new Button{Content="添加ROI",Tag="GroupRoiAdd"};add.Click+=(_,_)=>{if(rois.Count>=8){error.Text="最多8个ROI";return;}rois.Add(new(new(Guid.NewGuid().ToString("N"),(RoiKind)kinds.SelectedItem,0,0,100,100,10,0)));roiGrid!.Items.Refresh();};var remove=new Button{Content="删除ROI",Tag="GroupRoiDelete"};remove.Click+=(_,_)=>{if(roiGrid!.SelectedItem is RoiRow row){rois.Remove(row);roiGrid.Items.Refresh();}};tools.Children.Add(kinds);tools.Children.Add(add);tools.Children.Add(remove);DockPanel.SetDock(tools,Dock.Top);panel.Children.Add(tools);roiGrid=new DataGrid{ItemsSource=rois,AutoGenerateColumns=false,CanUserAddRows=false,Tag="GroupRoiGrid"};foreach(var key in new[]{"Kind","CenterX","CenterY","Width","Height","Radius","InnerRadius","AngleDegrees"})roiGrid.Columns.Add(new DataGridTextColumn{Header=key switch{"Kind"=>"类型","CenterX"=>"中心X","CenterY"=>"中心Y","Width"=>"宽度","Height"=>"高度","Radius"=>"半径","InnerRadius"=>"内半径",_=>"角度"},Binding=new Binding(key){UpdateSourceTrigger=UpdateSourceTrigger.LostFocus,ValidatesOnExceptions=true},IsReadOnly=key=="Kind",Width=new DataGridLength(1,DataGridLengthUnitType.Star)});roiGrid.BeginningEdit+=(_,e)=>{if(e.Row.Item is RoiRow r&&r.Kind==RoiKind.Polygon){e.Cancel=true;error.Text="此多边形不能在表格中修改。";}};panel.Children.Add(roiGrid);
  }else{var content=new StackPanel();if(editor.Kind==ParameterEditorKind.Enumeration){choices=new ComboBox{ItemsSource=editor.Choices,DisplayMemberPath="Name",Tag="GroupComplexChoices"};var value=node.Parameters.GetValueOrDefault(parameter.Name,parameter.DefaultValue??default);choices.SelectedItem=editor.Choices!.FirstOrDefault(c=>c.Value.ToString()==value.ToString());content.Children.Add(choices);}else foreach(var key in editor.Fields??new[]{parameter.Name}){var row=new DockPanel{Margin=new Thickness(0,8,0,0)};row.Children.Add(new TextBlock{Text=key,Width=150,VerticalAlignment=VerticalAlignment.Center});var spec=descriptor.Parameters.Single(p=>p.Name==key);var input=new TextBox{Tag="GroupComplexField:"+key,Text=node.Parameters.GetValueOrDefault(key,spec.DefaultValue??default).ToString()};fields[key]=input;if(editor.Kind is ParameterEditorKind.File or ParameterEditorKind.Folder){var browse=new Button{Content="浏览",Tag="GroupComplexBrowse"};DockPanel.SetDock(browse,Dock.Right);browse.Click+=(_,_)=>{if(editor.Kind==ParameterEditorKind.File){var d=new Microsoft.Win32.OpenFileDialog{Filter=editor.Filter??"所有文件|*.*"};if(d.ShowDialog(this)==true)input.Text=d.FileName;}else{var d=new Microsoft.Win32.OpenFolderDialog();if(d.ShowDialog(this)==true)input.Text=d.FolderName;}};row.Children.Add(browse);}row.Children.Add(input);content.Children.Add(row);}panel.Children.Add(content);}Content=panel;
 }
 void Confirm(){try{if(roiGrid is not null&&(!roiGrid.CommitEdit(DataGridEditingUnit.Cell,true)||!roiGrid.CommitEdit(DataGridEditingUnit.Row,true)))throw new InvalidOperationException("ROI包含无效数值，请修正后确定。");var values=new Dictionary<string,JsonElement>();if(choices is not null){if(choices.SelectedItem is not ParameterEditorChoice choice)throw new InvalidOperationException("请选择枚举值。");values[parameter.Name]=choice.Value.Clone();}foreach(var field in fields){var spec=descriptor.Parameters.Single(p=>p.Name==field.Key);object parsed=spec.Kind switch{ParameterKind.Text=>field.Value.Text,ParameterKind.Integer=>int.Parse(field.Value.Text,CultureInfo.InvariantCulture),ParameterKind.Boolean=>bool.Parse(field.Value.Text),_=>double.Parse(field.Value.Text,CultureInfo.InvariantCulture)};values[field.Key]=JsonSerializer.SerializeToElement(parsed);}save(values,parameter.Editor!.Kind==ParameterEditorKind.Roi?rois.Select(r=>r.Value()).ToArray():null);DialogResult=true;}catch(Exception e){error.Text=e.Message;}}
 public sealed class RoiRow{readonly RoiDocument source;public RoiRow(RoiDocument r){source=r;Kind=r.Kind;CenterX=r.CenterX;CenterY=r.CenterY;Width=r.Width;Height=r.Height;Radius=r.Radius;InnerRadius=r.InnerRadius;AngleDegrees=r.AngleDegrees;}public RoiKind Kind{get;}public double CenterX{get;set;}public double CenterY{get;set;}public double Width{get;set;}public double Height{get;set;}public double Radius{get;set;}public double InnerRadius{get;set;}public double AngleDegrees{get;set;}public RoiDocument Value()=>source with{CenterX=CenterX,CenterY=CenterY,Width=Width,Height=Height,Radius=Radius,InnerRadius=InnerRadius,AngleDegrees=AngleDegrees};}
}